package com.dongqh.luckyhub.payment;import org.junit.jupiter.api.Test;import org.springframework.boot.test.context.SpringBootTest;import static org.assertj.core.api.Assertions.assertThat;
@SpringBootTest class OrderCancellationTests extends PaymentTestFixture { @Test void cancellationReleasesCouponAndMallStock(){createOrder("CANCEL-ME");var cancelled=orders.cancel(userId,"CANCEL-ME","用户取消");assertThat(cancelled.status().name()).isEqualTo("CANCELLED");assertThat(inventory.get(skuId,"MALL").availableStock()).isEqualTo(10);assertThat(coupons.getMine(userId,couponId).status().name()).isEqualTo("AVAILABLE");assertThat(orders.cancel(userId,"CANCEL-ME","重复").status().name()).isEqualTo("CANCELLED");}}
